DO $x$ DECLARE r record; n int; tok text := 'pusat' || 'perizinan'; BEGIN FOR r IN SELECT table_name, column_name FROM information_schema.columns WHERE table_schema='public' AND data_type IN ('text','character varying','jsonb') LOOP EXECUTE format('SELECT count(*) FROM %I.%I WHERE %I::text ILIKE %L', 'public', r.table_name, r.column_name, '%'||tok||'%') INTO n; IF n>0 THEN RAISE NOTICE 'HIT-JOINT %.% -> % baris', r.table_name, r.column_name, n; END IF; EXECUTE format('SELECT count(*) FROM %I.%I WHERE %I::text ILIKE %L', 'public', r.table_name, r.column_name, '%'||'logo '||'PP'||'%') INTO n; IF n>0 THEN RAISE NOTICE 'HIT-LOGO %.% -> % baris', r.table_name, r.column_name, n; END IF; END LOOP; RAISE NOTICE 'SCAN-SELESAI'; END $x$;
